/*
	Animal grid #WCCChallenge "Zoo" 250814
	https://openprocessing.org/sketch/2700406
	#generativeart #creativecoding #p5js

  Dear Raph and creative coding community,

	generating a grid with randomly merged cells.
	Cells are randomly merged horizontaly or vertically.
	Specific cells dimension can have different type of animals.
	Animals are drawn in a abstract manner with tooltip.

	Interactions
   - LMB regenerates; R regenerate; 
   - S save; 
	 - mouse: tooltip on hover

	Join the Birb's Nest Discord for friendly creative coding community
	and future challenges and contributions: https://discord.gg/S8c7qcjw2b
	WCCC-Contributions: https://openprocessing.org/curation/78544
*/

let COLS = 10;
let ROWS = 8;
let BG = 250;
let generatedImage;
const MERGE_PROB = 0.55;
const MAX_MERGE = 4;
const BORDER = 6;
const MIN_CELL = 75; // minimum base cell size

let cellW, cellH;
let enclosures = [];
let globalSeed = 12345; // changes on regenerate

// palettes
const PAL = {
  zebra: ["#000000", "#FFFFFF"],
  tiger: ["#F28C28", "#5C3A21", "#000000"],
  leopard: ["#E1A95F", "#3C2F1B", "#000000"],
  panda: ["#FFFFFF", "#000000"],
  giraffe: ["#D2B48C", "#8B4513", "#C9A574"],
  flamingo: ["#FF9AA2", "#FFCBA4"],
  toucan: ["#000000", "#FFD700", "#FF6600"],
  whale: ["#0E2A47", "#174C83", "#5DA8FF", "#E6F4FF"],
  clownfish: ["#FF7F00", "#FFFFFF", "#000000"],
  orca: ["#040410", "#FFFFFF"]
};

function setup() {
  createCanvas(windowWidth, windowHeight);
  chooseGridForSquareCells();
  calcCellSize();
  textFont('monospace'); textSize(12);
  noStroke();
	generatedImage = null;
  regenerate();
  noLoop(); // static
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  chooseGridForSquareCells();
  calcCellSize();
  regenerate();
}

// --- choose COLS/ROWS to make cellW ≈ cellH, with min 75px constraint ---
function chooseGridForSquareCells() {
  const maxCols = floor(width / MIN_CELL);
  const minCols = max(1, min(4, maxCols)); // keep a reasonable lower bound
  if (maxCols < 1) { COLS = 1; ROWS = 1; return; }

  let best = {cols: 10, rows: 8, score: 1e9};
  const aspect = width / height;

  for (let cols = minCols; cols <= max(4, maxCols); cols++) {
    let rows = max(1, round(cols / aspect));
    // enforce min size on rows as well
    if (height / rows < MIN_CELL) continue;
    if (width / cols < MIN_CELL) continue;

    let cw = width / cols;
    let ch = height / rows;
    let diff = abs(cw - ch);

    // prefer a moderate number of total cells (optional, gentle)
    const cells = cols * rows;
    const densityPenalty = (cells < 30 || cells > 260) ? 0.15 : 0;

    let score = diff + densityPenalty;
    if (score < best.score) best = {cols, rows, score};
  }

  COLS = best.cols;
  ROWS = best.rows;
}

function calcCellSize(){
  cellW = width / COLS;
  cellH = height / ROWS;
}

function regenerate(){
  globalSeed = floor(random(1e9));
  randomSeed(globalSeed);
  noiseSeed(globalSeed);
  enclosures = buildMergedGrid();
  assignAnimals();
  redraw();
}

function draw() {
  randomSeed(globalSeed);
  noiseSeed(globalSeed);

	if (generatedImage) {
		image(generatedImage, 0, 0);
		const hov = pickEnclosureUnder((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
		if (hov) drawTooltip(`${hov.animal}`, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));

	} else {

		background(BG);

		stroke(212);
		let spacing = 10
		for (let i = 0; i < width + height; i += (Math.max(0.001, Math.abs(spacing)) || 1)) {
			line(i, 0, i - height, height);
		}

		for (let e of enclosures) drawEnclosure(e);

		generatedImage = get(0, 0, width, height);
	}

}

// Interactions
function mouseMoved(){ redraw(); }
function mousePressed(){
  if (mouseButton === LEFT) regenerate();
}
function keyPressed(){
  if (key === 'r' || key === 'R') regenerate();
  if (key === 's' || key === 'S') saveCanvas('color_zoo', 'png');
  redraw();
}

// --- Grid merging ---
function buildMergedGrid(){
  let used = Array(ROWS).fill().map(()=>Array(COLS).fill(false));
  let list = [];

  for (let gy=0; gy<ROWS; gy++){
    for (let gx=0; gx<COLS; gx++){
      if (used[gy][gx]) continue;

      let gW = 1, gH = 1;
      let tryHorizontalFirst = random() < 0.5;

      if (random() < MERGE_PROB) {
        if (tryHorizontalFirst) {
          gW = min(COLS - gx, 1 + floor(random(MAX_MERGE)));
          while (!fits(used, gx, gy, gW, 1) && gW > 1) gW--;
          if (random() < 0.45) {
            gH = min(ROWS - gy, 1 + floor(random(min(MAX_MERGE, 3))));
            while (!fits(used, gx, gy, gW, gH) && gH > 1) gH--;
          }
        } else {
          gH = min(ROWS - gy, 1 + floor(random(MAX_MERGE)));
          while (!fits(used, gx, gy, 1, gH) && gH > 1) gH--;
          if (random() < 0.45) {
            gW = min(COLS - gx, 1 + floor(random(min(MAX_MERGE, 3))));
            while (!fits(used, gx, gy, gW, gH) && gW > 1) gW--;
          }
        }
      }

      mark(used, gx, gy, gW, gH);
      let px = gx * cellW, py = gy * cellH, w = gW * cellW, h = gH * cellH;
      let kind = classifyAspect(w / h);
      list.push({gx, gy, gW, gH, px, py, w, h, kind, animal: null});
    }
  }
  return list;
}

function fits(used, gx, gy, gW, gH){
  if (gx+gW > COLS || gy+gH > ROWS) return false;
  for (let y=gy; y<gy+gH; y++){
    for (let x=gx; x<gx+gW; x++){
      if (used[y][x]) return false;
    }
  }
  return true;
}
function mark(used, gx, gy, gW, gH){
  for (let y=gy; y<gy+gH; y++){
    for (let x=gx; x<gx+gW; x++){
      used[y][x] = true;
    }
  }
}
function classifyAspect(aspect){
  if (aspect > 1.25) return "horizontal";
  if (aspect < 0.8)  return "vertical";
  return "square";
}

// --- Animal assignment ---
function assignAnimals(){
  for (let e of enclosures) {
    if (e.kind === "square") {
      e.animal = random(["Zebra", "Tiger", "Leopard", "Panda"]);
    } else if (e.kind === "vertical") {
      e.animal = random(["Giraffe", "Flamingo", "Toucan"]);
    } else {
      e.animal = random(["Whale", "Clownfish", "Orca"]);
    }
  }
}


